public class Solution {
  /**
   * 不装箱的多键排序：高 32 位 = ~priority（int 域内取反即"降序键"，且避开 -MIN_VALUE 陷阱），
   * 低 32 位 = 入队下标（升序次键）。long 的有符号比较先比高 32 位再比低 32 位，
   * 于是 Arrays.sort(long[]) 一次完成双键排序；键是全序，所以稳定性无关紧要。
   */
  public static int[] orderByPriority(int[] priorities, int[] jobIds) {
    if (priorities.length != jobIds.length) {
      throw new IllegalArgumentException("parallel arrays required");
    }
    int n = priorities.length;
    if (n == 0) return new int[0];
    long[] keys = new long[n];
    for (int k = 0; k < n; k++) {
      keys[k] = ((long) (~priorities[k]) << 32) | (k & 0xffffffffL);
    }
    java.util.Arrays.sort(keys);
    int[] out = new int[n];
    for (int k = 0; k < n; k++) out[k] = jobIds[(int) keys[k]];
    return out;
  }
}

