public class Solution {
  // 朴素：减法比较器 + 只有单键。极值优先级下 b - a 溢出，序直接乱掉；
  // 并列任务的入队顺序则交给 sort 的稳定性碰运气（Integer[] 恰好稳定，int[] 就不稳定）。
  public static int[] orderByPriority(int[] priorities, int[] jobIds) {
    if (priorities.length != jobIds.length) {
      throw new IllegalArgumentException("parallel arrays required");
    }
    Integer[] order = new Integer[priorities.length];
    for (int k = 0; k < order.length; k++) order[k] = k;
    java.util.Arrays.sort(order, (x, y) -> priorities[y] - priorities[x]);
    int[] out = new int[order.length];
    for (int k = 0; k < order.length; k++) out[k] = jobIds[order[k]];
    return out;
  }
}
